from collections import defaultdict
def try_rule(priority, conf_resolver):
    def f(g):
        h,w=len(g),len(g[0]); res=[r[:] for r in g]
        changed=True
        while changed:
            changed=False
            orders=[]
            for r in range(h):
                rows=defaultdict(list)
                for c in range(w):
                    v=g[r][c]
                    if v: rows[v].append(c)
                for v,cs in rows.items():
                    lo,hi=min(cs),max(cs)
                    for c in range(lo,hi+1): res[r][c]=v
            for c in range(w):
                cols=defaultdict(list)
                for r in range(h):
                    v=g[r][c]
                    if v: cols[v].append(r)
                for v,rs in cols.items():
                    lo,hi=min(rs),max(rs)
                    for r in range(lo,hi+1): res[r][c]=v
            # conflict resolve: any cell with multiple owners -> pick per resolver
            owners={}
            for r in range(h):
                for c in range(w):
                    if g[r][c]==0:
                        ow=set()
                        for rr in range(h):
                            if g[rr][c]!=0: ow.add((rr,g[rr][c]))
                        for cc in range(w):
                            if g[r][cc]!=0: ow.add((r,g[r][cc]))
                        if len(ow)>1:
                            owners[(r,c)]=conf_resolver(ow,priority)
            for (r,c),v in owners.items(): res[r][c]=v
        return res
    return f
