def build_f(conf):
    def f(g):
        h,w=len(g),len(g[0])
        out=[r[:] for r in g]
        # step A: gap fill in rows
        for r in range(h):
            for v in {g[r][c] for c in range(w) if g[r][c]}:
                cs=[c for c in range(w) if g[r][c]==v]
                for c in range(min(cs),max(cs)+1): out[r][c]=v
        for c in range(w):
            for v in {g[r][c] for r in range(h) if g[r][c]}:
                rs=[r for r in range(h) if g[r][c]==v]
                for r in range(min(rs),max(rs)+1): out[r][c]=v
        # step B: extend each color along its line until blocked, conflicts by conf
        outb=[r[:] for r in out]
        for v in sorted({x for r in g for x in r}):
            for r in range(h):
                cs=[c for c in range(w) if g[r][c]==v]
                if not cs: continue
                for c in cs:
                    # up
                    rr=r
                    while rr>=0 and g[rr][c]==0:
                        outb[rr][c]=v; rr-=1
                    # down
                    rr=r
                    while rr<h-1 and g[rr+1][c]==0:
                        outb[rr+1][c]=v; rr+=1
                    # left
                    cc=c
                    while cc>=0 and g[r][cc]==0:
                        outb[r][cc]=v; cc-=1
                    # right
                    cc=c
                    while cc<w-1 and g[r][cc+1]==0:
                        outb[r][cc+1]=v; cc+=1
            for c in range(w):
                rs=[r for r in range(h) if g[r][c]==v]
                if not rs: continue
                for r in rs:
                    cc=c
                    while cc>=0 and g[r][cc]==0:
                        outb[r][cc]=v; cc-=1
                    cc=c
                    while cc<w-1 and g[r][cc+1]==0:
                        outb[r][cc+1]=v; cc+=1
        return outb
    return f
