def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] and not seen[r][c]:
                v=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((v,cells))
