def comps_of(cells):
    cells=set(cells); seen=set(); out=[]
    for c in cells:
        if c in seen: continue
        stack=[c]; comp=[]
        while stack:
            x=stack.pop()
            if x in seen: continue
            seen.add(x); comp.append(x)
            r,c=x
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc)
                if n in cells and n not in seen: stack.append(n)
        out.append(comp)
    return out

