def solve(gi):
    h,w=len(gi),len(gi[0]); go=[[0]*w for _ in range(h)]
    # color cells
    cells={}; 
    for r in range(h):
        for c in range(w):
            v=gi[r][c]
            if v: cells.setdefault(v,[]).append((r,c))
    # completed bars: for each color, bar row = row with most cells; fill width-1 gaps between segments
    bar={}
    for v,cs in cells.items():
        from collections import Counter
        cnt=Counter(r for r,c in cs)
        br=cnt.most_common(1)[0][0]
        segs=[]
        cur=None
        for c in range(w):
            if (br,c) in set(cs):
                if cur is None: cur=[c,c]
                else: cur[1]=c
            else:
                if cur is not None: segs.append(cur); cur=None
        if cur is not None: segs.append(cur)
        gapcols=set()
        if len(segs)>=2:
            for a,b in zip(segs,segs[1:]):
                if b[0]==a[1]+1: pass
                elif b[0]==a[1]+2: gapcols.add(a[1]+1)
        bar[v]=(br,set(gapcols))
    # band assignment per column: colors with cells (orig or completed) in column
    colcolors={}
    for v,(br,gaps) in bar.items():
        occ=set()
        for r,c in cells[v]: occ.add(c)
        occ|=gaps
        for c in occ:
            colcolors.setdefault(c,[]).append((v,min(r for r,_ in cells[v]),max(r for _,r2 in [] ) if False else max(r for r,_ in cells[v])))
    # recompute max row properly
    colcolors={}
    for v,(br,gaps) in bar.items():
        for c in (set(c for _,c in cells[v])|gaps):
            colcolors.setdefault(c,[]).append((v,min(r for r,_ in cells[v]),max(r for r,_ in cells[v])))
    for c in colcolors:
        colcolors[c].sort(key=lambda x:(x[1],-x[2]))
    # bands
    bands={}
    for c,lv in colcolors.items():
        cur=0; bd={}
        for v,mn,mx in lv:
            if mn>=cur:
                # band [cur, mx] but ensure doesn't exceed... assign [cur, mx] clipped
                lo,hi=max(cur,mn),min(mx,h-1)
                if lo<=hi: bd[v]=(lo,hi)
                cur=mx+1
        bands[c]=bd
    # fill
    for c in range(w):
        for v,(lo,hi) in bands.get(c,{}).items():
            for r in range(lo,hi+1):
                go[r][c]=v
    return go

