def f(gi):
    h,w=len(gi),len(gi[0])
    go=[[0]*w for _ in range(h)]
    cells={}; 
    for r in range(h):
        for c in range(w):
            v=gi[r][c]
            if v: cells.setdefault(v,set()).add((r,c))
    # bar info: bar row per color = row with most cells; stub cols
    info={}
    for v,cs in cells.items():
        cnt={}
        for r,c in cs: cnt[r]=cnt.get(r,0)+1
        br=max(cnt,key=lambda r:cnt[r])
        spans=set(range(min(c for r,c in cs),max(c for r,c in cs)+1))
        if len(cs)<br*0+1: pass
        info[v]=(br,spans,set(c for r,c in cs if r!=br))
    # column occupancy: color occupies col c if c in bar span or c in stub cols
    occ={}
    for c in range(w):
        s=set()
        for v,(br,spans,stubs) in info.items():
            if c in spans or (stubs and c in stubs): s.add(v)
        occ[c]=s
    # build per-column bands: colors sorted by minrow, bands [0..minrow], [...minrow(curr)..minrow(next)-1], last to bottom
    for c,sv in occ.items():
        if len(sv)==1:
            v=next(iter(sv)); m=min(r for r,_ in cells[v])
            for r in range(m,h): go[r][c]=v
            continue
        order=sorted(sv,key=lambda v:min(r for r,_ in cells[v]))
        cur=0
        for i,v in enumerate(order):
            m=min(r for r,_ in cells[v])
            lo=cur if i==0 else (min(r for r,_ in cells[order[i-1]])+1)
            hi=m if i<len(order)-1 else h-1
            for r in range(lo,hi+1): go[r][c]=v
            cur=hi+1
    return go

