def f(gi):
    H=len(gi); W=len(gi[0]); out=[r[:] for r in gi]
    for r in range(H):
        row=gi[r]
        for c in range(1,W-1):
            if row[c]==0 and row[c-1]==row[c+1]:
                out[r][c]=row[c-1]
    # per column: collect colors with topmost row, process bottom-first, fill up through bg
    for c in range(W):
        occ={}
        for r in range(H):
            v=out[r][c]
            if v!=0: occ.setdefault(v,min(r,occ.get(v,99)))
        srcs=sorted([(v,occ[v]) for v in occ], key=lambda x:-x[1])
        for v,r0 in srcs:
            rr=r0-1
            while rr>=0 and out[rr][c]==0:
                out[rr][c]=v; rr-=1
    return out
