def f(gi):
    H=len(gi); W=len(gi[0]); out=[r[:] for r in gi]
    for r in range(H):
        for c in range(1,W-1):
            if gi[r][c]==0 and gi[r][c-1]==gi[r][c+1]:
                out[r][c]=gi[r][c-1]
    # collect color per column: last nonzero going down, plus horizontal fills? Use final grid columns
    # band rule: per odd column, top band determined by the run above; bottom band below the last row of that color
    for c in range(1,W,2):
        col=[out[r][c] for r in range(H)]
        # segment colors: scan bottom up, track changes
        segs=[]  # list of (color, bottom_row)
        cur=col[-1]; bot=-1
        for r in range(H-1,-1,-1):
            if col[r]!=cur:
                segs.append((cur,r)); cur=col[r]
        segs.append((cur,-1))
        # fill upwards: each color extends to its top boundary = row just above previous color's start... instead:
        # every zero cell takes color of nearest colored cell below or equal
        # i.e. bottom-most source fills upward until hitting a different source or edge
        srcs=sorted(segs,key=lambda x:x[1],reverse=True)  # bottom first
        painted=set()
        for v,bot in srcs:
            for r in range(bot+1,H):
                if col[r]==v: continue
                if r in painted: break
                if col[r]==0: col[r]=v; painted.add(r)
        for r in range(H): out[r][c]=col[r]
    return out
