def solve(variant='top'):
    def f(gi):
        H=len(gi); W=len(gi[0]); out=[r[:] for r in gi]
        for r in range(H):
            for c in range(1,W-1):
                if gi[r][c]==0 and gi[r][c-1]==gi[r][c+1]:
                    out[r][c]=gi[r][c-1]
        # horizontal extension of runs into odd columns
        def extend(run_start,run_end,color,row):
            for d in (-1,1):
                cc=(run_end+d) if d==1 else (run_start+d)
                while 0<=cc<W and out[row][cc]==0 and cc%2==1:
                    out[row][cc]=color; cc+=d
        for r in range(H):
            row=out[r]; c=0
            while c<W:
                if row[c]!=0:
                    s=c
                    while c<W and row[c]==row[s]: c+=1
                    e=c-1
                    extend(s,e,row[c],r)
                else: c+=1
        res=[r[:] for r in out]
        for c in range(1,W,2):
            col=[res[r][c] for r in range(H)]
            # sources = colored cells; paint upward, stop at non-bg
            srcs=[(v,r) for r,v in enumerate(col) if v!=0]
            order=sorted(srcs,key=lambda x:(x[1],-x[0]) if variant=='left' else (x[1],x[0]))
            # try: topmost first
            order=sorted(srcs,key=lambda x:x[1])
            done=set()
            for v,r0 in order:
                rr=r0-1
                while rr>=0 and col[rr]==0 and rr not in done:
                    col[rr]=v; done.add(rr)
            for r in range(H): res[r][c]=col[r]
        return res
